-- 2026-06-17 — Bengaluru locality -> RMP 2031 Planning District lookup
-- Source: RMP 2031 (Draft) Volume-4 Planning District Report + Index Map (BDA, Nov 2017).
-- PD numbering/names are VERBATIM from the live evidence_facts PDR-demographics fact
-- (authoritative). This table lets the parcel-context resolver map a geocoded
-- address locality/ward/village to its Planning District deterministically, without
-- the (unavailable) PD boundary polygons. Reference data: universal-read RLS, seed-only.
-- Generated deterministically from validated source JSON — do not hand-edit rows.

CREATE TABLE IF NOT EXISTS regulatory_data.district_localities (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  city          text NOT NULL DEFAULT 'Bengaluru',
  pd_number     int  NOT NULL,
  pd_code       text NOT NULL,
  pd_name       text NOT NULL,
  within_bbmp   boolean NOT NULL DEFAULT false,
  locality      text NOT NULL,
  locality_norm text NOT NULL,
  kind          text NOT NULL DEFAULT 'locality',
  confidence    text NOT NULL DEFAULT 'high',
  source        text NOT NULL,
  created_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_district_localities_norm ON regulatory_data.district_localities (locality_norm);
CREATE UNIQUE INDEX IF NOT EXISTS uq_district_localities ON regulatory_data.district_localities (city, locality_norm, pd_number);

ALTER TABLE regulatory_data.district_localities ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS district_localities_select_all ON regulatory_data.district_localities;
CREATE POLICY district_localities_select_all ON regulatory_data.district_localities FOR SELECT USING (true);

-- Idempotent re-seed: clear prior rows from these sources, then insert.
DELETE FROM regulatory_data.district_localities
  WHERE source IN ('RMP 2031 Vol-4 PDR — PD name','RMP 2031 Index Map (BDA, Nov 2017)');

ON CONFLICT (city, locality_norm, pd_number) DO NOTHING;
